import sympy
from sympy import Matrix, zeros, eye
from sympy.abc import x, y, z

# Top-level setup: named object bindings
I2 = eye(2)
I3 = eye(3)
O2 = zeros(2, 2)
O3 = zeros(3, 3)

def conditions(witness) -> list[bool]:
    h1, h2, neg_q = False, False, False
    
    # Case 1: witness is a tuple of two integers (n, m)
    # representing the ring Z_n and the ideal generated by m
    try:
        if isinstance(witness, tuple) and len(witness) == 2:
            n, m = witness
            if (isinstance(n, int) or (hasattr(n, 'is_integer') and n.is_integer)) and \
               (isinstance(m, int) or (hasattr(m, 'is_integer') and m.is_integer)):
                n_val = int(n)
                m_val = int(m)
                h1 = n_val >= 2
                h2 = (m_val * m_val) % n_val == 0
                neg_q = (m_val % n_val) != 0
                return [h1, h2, neg_q]
    except Exception:
        pass

    # Case 2: witness is a single SymPy Matrix M
    # representing the ring Z[M] and the ideal generated by M
    try:
        if hasattr(witness, 'is_Matrix') and witness.is_Matrix:
            h1 = True
            h2 = (witness**2).is_zero_matrix == True
            neg_q = witness.is_zero_matrix == False
            return [h1, h2, neg_q]
    except Exception:
        pass

    # Case 3: witness is a list of SymPy Matrices (generators of I)
    try:
        if isinstance(witness, list) and len(witness) > 0 and all(hasattr(mat, 'is_Matrix') and mat.is_Matrix for mat in witness):
            h1 = True
            h2 = all((m1 * m2).is_zero_matrix == True for m1 in witness for m2 in witness)
            neg_q = any(mat.is_zero_matrix == False for mat in witness)
            return [h1, h2, neg_q]
    except Exception:
        pass

    # Case 4: witness is a tuple (R, I) where R and I are lists of matrices
    try:
        if isinstance(witness, tuple) and len(witness) == 2:
            R, I = witness
            if isinstance(R, list) and isinstance(I, list) and \
               all(hasattr(m, 'is_Matrix') and m.is_Matrix for m in R) and \
               all(hasattr(m, 'is_Matrix') and m.is_Matrix for m in I):
                h1 = len(I) > 0
                h2 = all((m1 * m2).is_zero_matrix == True for m1 in I for m2 in I)
                neg_q = any(m.is_zero_matrix == False for m in I)
                return [h1, h2, neg_q]
    except Exception:
        pass

    # Case 5: witness is a tuple (R, I) from sympy.polys
    try:
        if isinstance(witness, tuple) and len(witness) == 2:
            R, I = witness
            if hasattr(R, 'ideal') and hasattr(I, 'ring'):
                h1 = I.ring == R
                try:
                    I2 = I * I
                except Exception:
                    gens = [g1 * g2 for g1 in I.gens for g2 in I.gens]
                    I2 = R.ideal(*gens)
                zero_ideal = R.ideal(0)
                h2 = I2 == zero_ideal
                neg_q = I != zero_ideal
                return [h1, h2, neg_q]
    except Exception:
        pass

    return [h1, h2, neg_q]

CONDITION_LABELS = [
    "H_1: I is an ideal of R",
    "H_2: The product of I with itself (I^2) is the zero ideal",
    "¬Q: The ideal I is not the zero ideal"
]

